import math
import sys

def dist(x1, y1, x2, y2):
    return math.sqrt((x1 - x2) ** 2 + (y1 - y2) ** 2)

def find_shortest_path(points, start):
    sorted_points = sorted(points, key=lambda point: dist(points[start-1], 0, points[start-1], points[start][1]))
    reachable_points = {point:start-1 for point in sorted_points if point == start}
    for i, point in enumerate(sorted_points):
        if reachable_points[point]:
            connected_points = [j for j in reachable_points if not reachable_points[j] and dist(sorted_points[connected_points[-1]], 0, sorted_points[j], 0) <= 1]
            if connected_points:
                reachable_points[point] = connected_points[0]
                continue
            if points.index(point) == i:
                break
            if point > start:
                each_move = min(dist(points[reached_point], 0, point, 0) for reached_point in reachable_points)
                if each_move >= dist(points[sorted_points.index(point)+1], 0, points[-1], 0):
                    break
    return min(dist(sorted_points[start], 0, point, 0) for point in range(start, len(sorted_points)))

