    # Function to perform the circular shift (R for R, L for L, etc.).
    def circular_shift(matrix, mode, col):
        directions = {"R": -1, "L": 1, "D": -1, "U": 1, "I": {}, "C": {}}
        if col in directions[mode]:
            for i in range(len(matrix)):
                if directions[mode][col] == -1:
                    newRow = (i - 1) % len(matrix)
                else:
                    newRow = (i + 1) % len(matrix)
                matrix[i][col], matrix[newRow][col] = matrix[newRow][col], matrix[i][col]

    # Counters for each mode and the index of the next operation.
    shift_count, next_op_index = 0, 0
    next_op_char = ""
    while next_op_index < len(operations):
        op = operations[next_op_index]
        if next_op_char == "R" or op == "R" or op == "CR":
            shift_count, next_op_index = max(0, shift_count + 1), next_op_index + 1
            circular_shift(matrix, "R", 1 + 2 * shift_count)
        elif next_op_char == "L" or op == "L" or op == "CL":
            shift_count, next_op_index = max(0, shift_count + 1), next_op_index + 1
            circular_shift(matrix, "L", 1 + 2 * shift_count)
        elif next_op_char == "D" or op == "D" or op == "CD":
            shift_count, next_op_index = max(0, shift_count + 1), next_op_index + 1
