def build_tree(distances):
    n = len(distances)
    parents = [i for i in range(n)]
    degrees = [1] * n  # Initialize all degrees to 1 to handle 0-distance situations

    for i in range(n - 1):
        for j in range(n):
            if distances[i][j] == 0:
                continue
            parent_of_vertex = -1
            for k in range(n):
                if distances[i][k] == j and k != i:
                    if parent_of_vertex == -1:
                        parent_of_vertex = k
                    continue
                elif k != i:
                    break
            else:
                parents[j] = parent_of_vertex
                if parent_of_vertex != -1 and parents[parent_of_vertex] != i:
                    return -1
                degrees[j] = max(degrees[j], degrees[parent_of_vertex] + 1)

    if any(degrees):
        return -1

    # At this point, we have a valid tree or no tree at all.
    for d in distances:
        if any(i != d[0] for i in range(1, n)):
