def is_stack_terminable(arr):
    stack = []
    for elem in arr:
        count = defaultdict(int)
        current = stack[-1] if stack else None
        for i in range(elem):
            if current != None and current != elem:
                if any(count[a] > 0 for a in stack):
                    break
                else:
                    stack.append(elem)
            else:
                stack.append(elem)
                break
        if stack and stack[-1] != elem:
            break
    return len(stack) == 0

def count_stack_terminable_subarrays(n, arr):
    result = 0
    for i in range(n):
        for j in range(i, n):
            if is_stack_terminable(arr[i:j+1]):
                result += 1
    return result

