    # For each vertex, check if it can be the maximum distance from a single vertex
    maximums = [0] * n
    for vertex, distances in graph.items():
        maximum = 0
        for neighbor in distances:
            maximum = max(maximum, distances[neighbor-1])
        maximums[vertex-1] = maximum

    # If the maximum distance for a vertex matches the given distance, the tree exists
    if max(maximums) in distances:
        return ([i]+[graph[i][j]] for i in range(n) for j in range(1, n) if distances[i] == maximums[i])

    return -1

