    rotate = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            rotate[m - 1 - i][j] = matrix[i][j]
    for i in range(n):
        for j in range(n):
            matrix[i][j] = rotate[i][j]

def down_rotate(matrix: List[List[int]], n: int) -> None:
    rotate = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            rotate[i][n - 1 - j] = matrix[m - 1 - i][j]
    for i in range(n):
        for j in range(n):
            matrix[i][j] = rotate[i][j]

def inverse_permutation(perm: List[int]) -> List[int]:
    inv_perm = [x for x in range(1, len(perm) + 1)]
    for i in range(len(perm)):
        inv_perm[perm[i] - 1], inv_perm[i] = inv_perm[i], inv_perm[perm[i] - 1]
    return inv_perm

def apply_operations(matrix: List[List[int]], operations: str, n: int) -> None:
    for op in operations:
        if op == 'R':
            right_rotate(matrix, n)
        elif op == 'L':
            left_rotate(matrix, n)
        elif op == 'D':
            down_rotate(matrix, n)
        elif op == 'U':
            up_rotate(matrix, n)
        elif op == 'I':
            matrix = inverse_permutation(sum(matrix, []))
        elif op == 'C':
            matrix = [[row[i] for row in matrix] for i in range(n)]

def solve(test_case: int):
