        matrix.append(row)
    operations = input()
    apply_operations(matrix, operations, n)
    for row in matrix:
        print(' '.join(map(str, row)))

if __name__ == "__main__":
    t = int(input())
    for test_case in range(1, t + 1):
        solve(test_case)
