from collections import Counter

def solve(k, boxes):
    total_sum = sum(sum(numbers) for numbers in boxes)
    if total_sum % k != 0:
        return "No"

    target_sum = total_sum // k
    choices = Counter()
    lasts = [int(-1e9 // 2)] * k
    for i in range(k):
        n = len(boxes[(i + 1) % k])
        numbers = sorted(boxes[(i + 1) % k])
        for j in range(n):
            current_sum = 0
            for number in numbers[:j + 1]:
                current_sum += number
                choices[number] += j
                while current_sum > target_sum and j:
                    j -= 1
                    choices[boxes[(i + 1 - j) % k][j-1]] -= 1
                    if choices[boxes[(i + 1 - j) % k][j-1]] == 0:
                        choices.pop(boxes[(i + 1 - j) % k][j-1])
                    if not choices:
                        break
                    current_sum -= boxes[(i + 1 - j) % k][j-1]
                    for x in range(j-1, -1, -1):
                        if j > x + 1:
                            choices[boxes[(i + 1 - x) % k][x-1]] -= 1
                            if choices[boxes[(i + 1 - x) % k][x-1]] == 0:
                                choices.pop(boxes[(i + 1 - x) % k][x-1])
            if current_sum != target_sum:
                break
        if j == n:
            for number in numbers[:j]:
                choices[number] += 1
                if j > choices[number] and choices[number] > lasts[j - 1]:
                    lasts[j] = choices[number]
                    last = number
            while j:
                for number in numbers[:j]:
                    choices[number] -= 1
                    if j > choices[number] and choices[number] > lasts[j - 1]:
                        lasts[j] = choices[number]
                        last = number
                j -= 1
            if j != 0 or lasts[j - 1] < choices[last]:
                choices[last] -= 1
        if j == n:
            return "Yes"
        for number in numbers[:j]:
            choices[number] -= 1
            if j > choices[number] and choices[number] > lasts[j - 1]:
                lasts[j] = choices[number]
                last = number
        if j == 0:
            for number in numbers:
                choices[number] -= 1
                if j > choices[number] and choices[number] > lasts[j - 1]:
                    lasts[j] = choices[number]
                    last = number
    return "Yes"

